local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["c903f8b7aa153bd7"] = { "Cerca di mantenere l'equilibrio in ogni cosa, {class}. È lì che si trova la vera armonia.", "." },
  ["c904e35356da9522"] = { "Ok, allora dove diavolo è? Aspetta un attimo! Sei ubriaco?", "." },
  ["c90933b74df7316a"] = { "Nessuno lo sa. Perché gli unici che l'hanno fatto non sono mai tornati. Quando gli skycutter facevano ancora la spola tra Valanaar e New Eldranaar o Shen'dramar, a volte un incidente o qualche altra disgrazia faceva cadere qualcuno fuori bordo. Quando succedeva, non rallentavano nemmeno la nave. Non aveva senso.\n\nPer quanto ne sappiamo, chiunque sia caduto è ancora là fuori... a precipitare senza fine, per sempre.", "." },
  ["c90bfffef5e4a6c4"] = { "Il Signore del Fuoco e i suoi simili un tempo dominavano questo mondo intero, mortale. Come servitore degli Dei Antichi, combatté contro i Titani per il dominio di questo pianeta. I Titani vittoriosi esiliarono il mio padrone e i suoi simili nel Piano Elementale, dove resteranno prigionieri fino alla fine dei tempi.", "." },
  ["c90e3cee88f51945"] = { "Non posso permetterti di entrare nel Tempio! Devo distruggerti per il tuo bene!", "." },
  ["c912b44905c1920b"] = { "Sorgi, mio campione!", "." },
  ["c917e996f9f43c00"] = { "Che io sappia, qui a Dun Morogh non ci sono incantatori. Dovrai andare a ⟦Ironforge=Forgiardente⟧ se vuoi imparare la professione di incantatore.", "." },
  ["c9186156338cb3d5"] = { "%s emette un gemito di dolore.", "." },
  ["c91f79a0e4b4695e"] = { "%s si spacca in due!", "." },
  ["c92652b31b50e2a6"] = { "Erbe... devi parlare con Jandi, al suo arboreto nel Varcolargo. Ci sono dei gradini di legno dietro Asoran's Market, nella Valle della Saggezza. Salili fino al livello superiore del Varcolargo e la troverai.", "." },
  ["c92cb8d6b8c02eaa"] = { "<Un/Una> <Cacciatore/Cacciatrice>, eh? Allora dovrai parlare con Thorfin Stoneshield, laggiù nel Distretto dei Nani.\n\nAh, e digli pure che se metto ancora una volta il piede nei bisogni del suo famiglio, finirà ad addestrare gli altri Cacciatori da dietro le sbarre delle ⟦Stockade=Segrete di Roccavento⟧!", "." },
  ["c936d36a0114741d"] = { "Qualche spicciolo per un povero cieco? ...Come sarebbe a dire che non sono cieco? ...NON SONO CIECO! CI VEDO!! È un miracolo!", "." },
  ["c939e169b7bc66bb"] = { "Teschi darai e teschi prenderò.", "." },
  ["c942c5a882369509"] = { "L'ultima risata sarà la mia... vedranno! Oh, ciao, {class}, non ti avevo visto.", "." },
  ["c9470946339ce562"] = { "Sono fiero dei tuoi successi, {name}. Hai portato a termine l'ultimo compito che ti ho affidato?", "." },
  ["c94acbb9c4791a7c"] = { "Flotta nemica laggiù! Fuoco!", "." },
  ["c94fa0daa306db84"] = { "Non sono qui per farti del male, Kharan. Mi manda Gor'shak. Mi ha detto che mi avresti parlato della principessa.", "." },
  ["c94ff31bf8094dc6"] = { "Niente prigionieri! Cacciate questi pagani dalle nostre terre!", "." },
  ["c95899b4740dba7d"] = { "Ah! Ecco la mia chiave a cricchetto! Ora riattacchiamo questi frammenti di pergamena.", "." },
  ["c95d651498835cb9"] = { "Intrusi! Invasori! L'Occhio Onniveggente è stato rubato! Quel cane miserabile di {name} ce l'ha in suo possesso!", "." },
  ["c95e011b2aa4f121"] = { "%s si schiarisce la gola.", "." },
  ["c961580be5ea4ce2"] = { "Ho qui gli ordini per un attacco alle forze dell'Alleanza nei campi centrali. Mi serve qualcuno che li porti al capo dell'assalto.", "." },
  ["c97cca7b0f11eca2"] = { "La mia morte conta poco... il Martello calerà comunque!", "." },
  ["c97ccc5443452b2e"] = { "Quante barre di metallo ha raccolto finora l'⟦Horde=Orda⟧?", "." },
  ["c98275039b07285c"] = { "Posso aiutarti in qualcosa, {name}? Altrimenti ho una spedizione di cui occuparmi.", "." },
  ["c991025571cadb85"] = { "Per il Capoguerra!", "." },
  ["c992028ac5e37915"] = { "Dove cercare una compagnia cupa e tenebrosa, se non nella parte buia di ⟦Ironforge=Forgiardente⟧, che porta il nome quanto mai azzeccato della Caverna degli Inganni? Lì troverai di sicuro Thistleheart, probabilmente intento a evocare qualche creatura immonda ai suoi ordini.", "." },
  ["c995b1b2b4b54341"] = { "Sono fuori dalla pancia di questa bestia da nemmeno due minuti e qualcuno mi chiede già delle mie abitudini in bagno??? <Signorino/Signorina>, ti avrei preso a schiaffi per una domanda simile, se non fosse che mi hai appena salvato la vita!\n\nComunque! Grazie per l'aiuto. Magari posso ricambiare?", "." },
  ["c9a8cd3ed283b656"] = { "Osate interferire con la prova di questo essere? La battaglia va combattuta da soli! Soffrirete tutti per questa indiscrezione.", "." },
  ["c9b19cd8c1d8a663"] = { "Non posso insegnarti nulla che tu non sappia già. Però la conoscenza di mio padre supera di gran lunga la mia. Entra e parla con lui. Buona fortuna!", "." },
  ["c9b5ac40c044a010"] = { "Molte casse di rifornimenti chiuse a chiave sono andate perdute quando i naga hanno invaso la ⟦Zoram Strand=Spiaggia di Zoram⟧, a ⟦Ashenvale=Valtetra⟧.", "." },
  ["c9b6d5b11881b64f"] = { "Helene Peltskinner ha anni di esperienza nello scuoiare animali per Adele Fielder, che ne ricava oggetti in cuoio. Trovi Helene nella sua casa vicino al ⟦Crystal Lake=Lago di Cristallo⟧.", "." },
  ["c9b80fff01718987"] = { "Affrontate il mio campione, mortali!", "." },
  ["c9bd63c1d9142ff7"] = { "Soffrirai in eterno, {race}.", "." },
  ["c9bf695140460fa9"] = { "%s muore.", "." },
  ["c9cdb855939ed829"] = { "Gran signore Fordring, stai bene?", "." },
  ["c9d24e369ebe999f"] = { "Il tuo destino è segnato!", "." },
  ["c9d3709fd79ce95f"] = { "Questa guerra non è finita, è appena cominciata! Abbiamo uomini e donne coraggiosi che combattono il nemico dentro ⟦Ahn'Qiraj=Ahn'qiraj⟧ giorno e notte, {name}. Non passerà molto prima che la città dei Qiraji cada.", "." },
  ["c9ec0385ebf67490"] = { "In posizione, ragazzi! Le bestiacce ci sono addosso. Aspettate il mio segnale!", "." },
  ["c9ec4d147a6c131f"] = { "Meno chiacchiere e più ascolto.", "." },
  ["c9ec82feabcae70d"] = { "Salute, {name}. Sei qui per conoscere la storia di ⟦Ironforge=Forgiardente⟧?", "." },
  ["c9f10611be6c4a0a"] = { "Iniziate il rituale, miei servitori. Dobbiamo ricacciare nel vuoto il cuore di Hakkar!", "." },
  ["c9f64b5a895ed81e"] = { "Avrò novantanove problemi, ma ballare non è uno di questi! Buona Veglia delle Ombre, {name}!", "." },
  ["c9fe48069395b38f"] = { "Queste caverne un tempo erano un tempio di speranza per la rinascita delle ⟦Barrens=Savane⟧. Ora sono sale da incubo.", "." },
})
